-- 0001_init: core commerce schema.
-- Conventions:
--   * Primary keys are UUIDv7 generated by the application (time-ordered => append-friendly B-trees).
--   * Money is BIGINT minor units (cents) + ISO-4217 currency. Never floating point.
--   * Every table has created_at/updated_at; mutable aggregates carry a version for optimistic checks.
--   * Constraints enforce invariants in the database, not only in application code.

CREATE TABLE products (
  id            uuid PRIMARY KEY,
  sku           text NOT NULL,
  name          text NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
  description   text NOT NULL DEFAULT '' CHECK (length(description) <= 5000),
  price_cents   bigint NOT NULL CHECK (price_cents >= 0),
  currency      char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  active        boolean NOT NULL DEFAULT true,
  version       integer NOT NULL DEFAULT 1,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT products_sku_uniq UNIQUE (sku),
  CONSTRAINT products_sku_format CHECK (sku ~ '^[A-Z0-9][A-Z0-9_-]{0,63}$')
);
-- Catalog listing uses keyset pagination over (id) filtered to active products.
CREATE INDEX products_active_id_idx ON products (id) WHERE active;

-- Stock is kept in its own narrow table so the hot row being updated on every order
-- is small (fewer bytes rewritten per MVCC update, more HOT updates, less WAL).
CREATE TABLE inventory (
  product_id    uuid PRIMARY KEY REFERENCES products (id) ON DELETE RESTRICT,
  available     integer NOT NULL CHECK (available >= 0),   -- the oversell guard of last resort
  reserved      integer NOT NULL DEFAULT 0 CHECK (reserved >= 0),
  updated_at    timestamptz NOT NULL DEFAULT now()
) WITH (fillfactor = 70); -- leave room on each page for HOT updates

CREATE TABLE orders (
  id            uuid PRIMARY KEY,
  user_id       uuid NOT NULL,
  status        text NOT NULL CHECK (status IN ('PENDING_PAYMENT','PAID','CANCELLED','FULFILLED')),
  total_cents   bigint NOT NULL CHECK (total_cents >= 0),
  currency      char(3) NOT NULL,
  item_count    integer NOT NULL CHECK (item_count > 0),
  version       integer NOT NULL DEFAULT 1,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now()
);
-- "My orders" newest-first keyset pagination.
CREATE INDEX orders_user_created_idx ON orders (user_id, created_at DESC, id DESC);
-- Background jobs: expire unpaid orders.
CREATE INDEX orders_pending_created_idx ON orders (created_at) WHERE status = 'PENDING_PAYMENT';

CREATE TABLE order_items (
  order_id          uuid NOT NULL REFERENCES orders (id) ON DELETE CASCADE,
  line_no           smallint NOT NULL CHECK (line_no > 0),
  product_id        uuid NOT NULL REFERENCES products (id),
  sku               text NOT NULL,
  name              text NOT NULL,
  quantity          integer NOT NULL CHECK (quantity > 0),
  unit_price_cents  bigint NOT NULL CHECK (unit_price_cents >= 0),
  PRIMARY KEY (order_id, line_no)
);
CREATE INDEX order_items_product_idx ON order_items (product_id);

-- Idempotency keys live apart from orders so they can be purged on a short retention
-- (and so orders can later be range-partitioned without breaking key uniqueness).
CREATE TABLE idempotency_keys (
  user_id       uuid NOT NULL,
  key           text NOT NULL CHECK (length(key) BETWEEN 8 AND 128),
  request_hash  text NOT NULL,
  order_id      uuid NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, key)
);
CREATE INDEX idempotency_keys_created_idx ON idempotency_keys (created_at);

-- Transactional outbox: events are written in the same transaction as the state change
-- and relayed to Kafka asynchronously => no dual-write inconsistency.
CREATE TABLE outbox (
  id              bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  aggregate_type  text NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      text NOT NULL,
  payload         jsonb NOT NULL,
  created_at      timestamptz NOT NULL DEFAULT now()
);

-- Append-only audit trail of privileged and state-changing actions.
CREATE TABLE audit_log (
  id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  actor_id      text NOT NULL,
  action        text NOT NULL,
  entity_type   text NOT NULL,
  entity_id     text NOT NULL,
  data          jsonb NOT NULL DEFAULT '{}'::jsonb,
  request_id    text,
  created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_log_entity_idx ON audit_log (entity_type, entity_id, created_at DESC);

-- Application role must not be able to rewrite history.
-- (Applied in deploy: REVOKE UPDATE, DELETE ON audit_log FROM shopcore_app;)
